package com.example.meetomxh.supabase;
import com.example.meetomxh.models.*;
import org.json.*;
import java.util.*;
public final class Dto {
 public static String nullable(JSONObject o,String key){return o==null||o.isNull(key)?null:o.optString(key,null);}
 public static String asset(String id){return id==null||id.isEmpty()?"":"asset://"+id;}
 public static String assetId(String ref){return ref!=null&&ref.startsWith("asset://")?ref.substring(8):ref;}
 public static long time(String t){ServerTime s=ServerTime.parse(t);return s==null?0:s.toDate().getTime();}
 public static User user(JSONObject o){User u=new User();u.setUid(o.optString("profile_id",o.optString("id")));u.setFullName(o.optString("display_name","Người dùng"));u.setAvatarUrl(asset(nullable(o,"avatar_asset_id")));u.setCoverUrl(asset(nullable(o,"cover_asset_id")));u.setBio(o.optString("bio",""));u.setDateOfBirth(nullable(o,"birth_date"));u.setGender(nullable(o,"gender"));u.setProfileCompleted(o.optBoolean("onboarding_completed"));return u;}
 public static Post post(JSONObject o){Post p=new Post();p.setPostId(o.optString("id"));p.setAuthorUid(nullable(o,"author_id"));JSONObject a=o.optJSONObject("author");p.setUserName(a==null?"Người dùng":a.optString("display_name","Người dùng"));p.setUserAvatar(a==null?"":asset(nullable(a,"avatar_asset_id")));p.setContent(o.optString("body",""));p.setVisibility(o.optString("audience","public"));p.setType(o.optString("kind").equals("share")?"share":"normal");p.setOriginalPostId(nullable(o,"original_post_id"));p.setLikesCount(o.optInt("reactions_count"));p.setCommentsCount(o.optInt("comments_count"));p.setSharesCount(o.optInt("shares_count"));p.setLiked(!o.isNull("my_reaction"));p.version=o.optLong("version",1);p.serverCreatedAt=o.optString("created_at");p.setCreatedAt(time(p.serverCreatedAt));p.setUpdatedAt(time(o.optString("updated_at")));p.setTimeAgo("Vừa cập nhật");List<String> assets=new ArrayList<>();JSONArray media=o.optJSONArray("media");if(media!=null)for(int i=0;i<media.length();i++)assets.add(asset(media.optJSONObject(i).optString("asset_id")));p.setImageUrls(assets);if(!assets.isEmpty()){p.setPostImage(assets.get(0));p.setMediaType("image");}return p;}
 public static ChatMessage message(JSONObject o){ChatMessage m=new ChatMessage();m.setMessageId(o.optString("id"));m.setSenderId(nullable(o,"sender_id"));m.seq=o.optLong("seq");m.version=o.optLong("version");m.setCreatedAt(ServerTime.parse(o.optString("created_at")));m.setRecalled(!o.optString("state").equals("sent"));m.setText(o.isNull("body")?"":o.optString("body"));m.setType(o.optString("kind").equals("media")?"image":"text");JSONArray media=o.optJSONArray("media");if(media!=null&&media.length()>0)m.setImageUrl(asset(media.optJSONObject(0).optString("asset_id")));JSONObject reply=o.optJSONObject("reply");m.setReplyToMessageId(nullable(o,"reply_to_message_id"));if(reply!=null){m.setReplyToSenderId(nullable(reply,"sender_id"));m.setReplyPreview(reply.isNull("body")?"Tin nhắn đã thu hồi":reply.optString("body"));}return m;}
 public static Chat chat(JSONObject o){Chat c=new Chat();c.setChatId(o.optString("id"));c.setType(o.optString("kind"));c.title=o.optString("title","Cuộc trò chuyện");c.state=o.optString("state");c.role=o.optString("role");c.version=o.optLong("version");c.highWater=o.optLong("high_water");c.lastReadSeq=o.optLong("last_read_seq");c.lastDeliveredSeq=o.optLong("last_delivered_seq");c.unreadCount=o.optLong("unread_count");c.setCreatedAt(ServerTime.parse(o.optString("created_at")));c.setUpdatedAt(ServerTime.parse(o.optString("updated_at")));JSONObject last=o.optJSONObject("last_message");if(last!=null){ChatMessage m=message(last);c.setLastMessageId(m.getMessageId());c.setLastMessage(m.getDisplayText());c.setLastMessageType(m.getType());c.setLastMessageSenderId(m.getSenderId());c.setLastMessageAt(m.getCreatedAt());}return c;}
 public static Comment comment(JSONObject o){Comment c=new Comment();c.setCommentId(o.optString("id"));c.setPostId(o.optString("post_id"));c.setAuthorUid(nullable(o,"author_id"));c.setAuthorName("Thành viên");c.setContent(o.isNull("body")?"Bình luận đã xóa":o.optString("body"));c.setCreatedAt(time(o.optString("created_at")));c.parentId=nullable(o,"parent_id");c.state=o.optString("state");c.version=o.optLong("version",1);return c;}
}
